const numberText=(v,unit='%')=>typeof v==='number'&&Number.isFinite(v)?v.toFixed(2)+unit:'待数据';
function requirement(label,key,test,target,d){const spec=definitions.find(x=>x[0]===key);const bounds=spec?[spec[2],spec[3]]:[-100,100];const valid=typeof d[key]==='number'&&Number.isFinite(d[key])&&d[key]>=bounds[0]&&d[key]<=bounds[1];return {label,value:valid?numberText(d[key],key==='volume'?' 倍':'%'):'待有效数据',target,status:valid?(test(d[key])?'yes':'no'):'unknown'};}
function explainSignals(d){return{dip:[requirement('60日回撤','drawdown',v=>v<=-15,'≤ −15%',d),requirement('收盘收复前日高点','stabilize',v=>v>0,'> 0%',d),requirement('量比','volume',v=>v>=1,'≥ 1 倍',d)],trend:[requirement('SPY 相对50日均线','market50',v=>v>0,'> 0%',d),requirement('SOXX 相对50日均线','sector',v=>v>0,'> 0%',d),requirement('个股相对50日均线','stock',v=>v>0&&v<=10,'> 0% 且 ≤ 10%',d),requirement('量比','volume',v=>v>=1.2,'≥ 1.2 倍',d)]};}
const previousRender=render;
render=function(){previousRender();const evidence=explainSignals(current);for(const [key,title]of [['dip','回撤企稳'],['trend','趋势确认']]){const rows=evidence[key];$('evidence-'+key).innerHTML=`<h3>${title}</h3>`+rows.map(r=>`<div class="evidence-row"><div>${esc(r.label)}<small>触发条件 ${esc(r.target)}</small></div><strong class="${r.status}">${esc(r.value)}</strong></div>`).join('');}
 $('relative-strength').textContent='20日相对SOXX表现：'+numberText(current.relative20);$('date-warning').textContent=current.aligned===false?'跨资产日期或数据尚未对齐，趋势候选暂不成立。':'技术候选只表示价格条件满足；还需要估值与基本面确认。';
 const r=evaluate(current);for(const key of ['panic','trend']){const count=r[key].filter(x=>x.status!=='unknown').length;$(`${key}-score`).textContent=count?r[key].filter(x=>x.status==='yes').length:'—';$(`${key}-checks`).insertAdjacentHTML('beforeend',`<p class="muted">已满足 ${r[key].filter(x=>x.status==='yes').length} 项 · 未满足 ${r[key].filter(x=>x.status==='no').length} 项 · 未知 ${5-count} 项</p>`);}
 if(mode==='auto'){const active=EntryLayers(current);const path=active.dip?evidence.dip:active.trend?evidence.trend:evidence.dip.filter(x=>x.status==='yes').length/3>=evidence.trend.filter(x=>x.status==='yes').length/4?evidence.dip:evidence.trend;const missing=path.filter(x=>x.status!=='yes');$('next').innerHTML=missing.map(x=>`<li>${esc(x.label)}：当前 ${esc(x.value)}，需要 ${esc(x.target)}。</li>`).join('')+(current.aligned===false?'<li>等待市场、行业和个股数据日期对齐。</li>':'')+'<li>估值与基本面仍待确认，不影响技术层独立观察。</li>';}
};
let watchRequest=null,watchUpdated=0;
async function refreshWatchlist(force=false){if(watchRequest||(!force&&Date.now()-watchUpdated<900000))return;watchRequest=true;$('watch-status').textContent='正在获取关注列表…';try{const response=await fetch('/api/watchlist',{signal:AbortSignal.timeout(30000)});if(!response.ok)throw Error();const d=await response.json();watchUpdated=Date.now();$('watch-status').textContent=`${d.date||'日期未知'} · 有效 ${d.covered} / ${d.total} · ${d.breadth===null?'样本不足，暂不计算比例':d.above+' / '+d.covered+' 站上50日均线（'+d.breadth.toFixed(0)+'%）'}`;const prior=window.watchPrevious||new Map();let changes=0;
 const analyzed=d.rows.map(r=>{let state,reason,next,rank;
 if(!r.included){state='数据待复核';reason=({review:'价格跳变待核实',stale:'价格数据已过期',missing:'来源暂缺'}[r.status]||'日期未对齐');next='取得同日有效数据';rank=0;}
 else if(r.drawdown<=-15){state='回撤观察';reason='60日回撤 '+numberText(r.drawdown);next='查看企稳、估值及基本面条件';rank=1;}
 else if(r.ma50>0&&r.ma50<=10&&r.volume>=1.2){state='趋势观察';reason='站上50日线，量比 '+numberText(r.volume,' 倍');next='核对市场、行业与估值';rank=1;}
 else{state='继续等待';reason='50日偏离 '+numberText(r.ma50)+' · 量比 '+numberText(r.volume,' 倍');next=r.ma50>10?'等待价格或估值条件改善':'查看尚未满足的价格条件';rank=2;}
 const changed=prior.has(r.symbol)&&prior.get(r.symbol)!==state;if(changed)changes++;return{...r,state,reason,next,rank:changed?-1:rank,changed};});
 $('brief-change').textContent=prior.size?(changes?changes+' 个标的的观察状态发生变化，已排在前面。':'本次刷新未发现观察状态变化。'):'首次观察 · '+analyzed.filter(r=>r.rank===1).length+' 个标的值得查看价格条件；尚无变化基线。';
 window.watchPrevious=new Map(analyzed.map(r=>[r.symbol,r.state]));
 $('watch-rows').innerHTML=analyzed.sort((a,b)=>a.rank-b.rank).map(r=>`<tr data-symbol="${esc(r.symbol)}" data-selected="${r.symbol===$('symbol').value}"><td><button class="symbol-link" data-observe="${esc(r.symbol)}">${esc(r.symbol)}</button></td><td><span class="watch-state">${esc(r.state)}</span>${r.changed?'<br><span class="muted">本次变化</span>':''}</td><td>${esc(r.reason)}</td><td>${esc(r.next)}</td><td>${esc(r.date||'日期未知')}</td></tr>`).join('');
 $('watch-rows').querySelectorAll('[data-observe]').forEach(b=>b.onclick=()=>{$('symbol').value=b.dataset.observe;$('symbol').dispatchEvent(new Event('change'));$('stock-detail').focus({preventScroll:true});$('stock-detail').scrollIntoView({block:'start',behavior:'smooth'});});
 }catch{$('watch-status').textContent='关注列表获取失败，请用顶部按钮重试。';$('brief-change').textContent='本次列表未能更新，暂不能比较观察状态。';$('watch-rows').innerHTML='<tr><td colspan="5">暂时无法获取，点击“刷新列表”重试。</td></tr>';}finally{watchRequest=false;}}
$('refresh-watch').onclick=()=>refreshWatchlist(true);render();refreshWatchlist();setInterval(()=>{if(!document.hidden)refreshWatchlist();},900000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){refreshWatchlist();if(mode==='auto'&&!$('refresh').disabled)refresh();}});
